prompts = {p['id']: p for p in dev['prompts']}

stats = {}
for pid, human_win in labels.items():
    p = prompts[pid]
    s = f\"{p['topic']}|{p['length']}\"
    j = p['judge_win']
    if s not in stats:
        stats[s] = {'pos_total': 0, 'pos_human_win': 0, 'neg_total': 0, 'neg_human_win': 0}
    if j:
        stats[s]['pos_total'] += 1
        if human_win:
            stats[s]['pos_human_win'] += 1
    else:
        stats[s]['neg_total'] += 1
        if human_win:
            stats[s]['neg_human_win'] += 1

print(f'{\"Stratum\":<15} | {\"Judge=1 (n, human=1, rate)\":<30} | {\"Judge=0 (n, human=0, rate)\":<30}')
