for s in sorted(stats.keys()):
    st = stats[s]
    pos_rate = st['pos_human_win'] / st['pos_total'] if st['pos_total'] else 0
    neg_rate = (st['neg_total'] - st['neg_human_win']) / st['neg_total'] if st['neg_total'] else 0
